steps.run:
$ErrorActionPreference = 'Stop'
$Support = Join-Path $env:RUNNER_TEMP 'packaged-support'
$Selection = Get-Content (Join-Path $Support 'selection.json') -Raw | ConvertFrom-Json -AsHashtable
$Artifacts = Join-Path $env:RUNNER_TEMP 'packaged-candidates'
New-Item -ItemType Directory -Path $Artifacts | Out-Null
$Sha = $Selection.sourceCommit
if ($Sha -notmatch '^[a-f0-9]{40}$') { throw 'Exact candidate source required.' }
$Names = [ordered]@{ windows="developer-windows-candidate-$Sha"; wsl="developer-wsl-candidate-$Sha" }
foreach ($Language in @('rust','c','java','dotnet','go','typescript')) {
    $Names[$Language] = "developer-$Language-tools-candidate-$Sha"
}
$Selection.artifacts = @{}
foreach ($Name in $Names.Keys) {
    $Destination = Join-Path $Artifacts $Name
    & gh run download $Selection.candidateRuns.developer.id --repo KirilsTurkins/latent-service-fabric --name $Names[$Name] --dir $Destination
    if ($LASTEXITCODE -ne 0) { throw "Candidate download failed: $Name" }
    $Selection.artifacts[$Name] = $Destination
}
$Destination = Join-Path $Artifacts 'native'
& gh run download $Selection.candidateRuns.runtime.id --repo KirilsTurkins/latent-service-fabric --name "native-runtime-candidate-development-test-$Sha" --dir $Destination
if ($LASTEXITCODE -ne 0) { throw 'Native candidate download failed.' }
$Selection.artifacts.native = $Destination
$Selection.trust = @{
    developerPolicy=(Join-Path $Support 'developer-policy.json'); runtimePolicy=(Join-Path $Support 'runtime-policy.json');
    trustedRoot=(Join-Path $Support 'trusted_root.jsonl'); trustedRootSha256=$Selection.verificationInputs.trustedRootSha256;
    hostVerifier=(Join-Path $Support 'gh.exe'); hostVerifierSha256=$Selection.verificationInputs.verifierSha256.windows;
    guestVerifier=(Join-Path $Support 'gh-linux'); guestVerifierSha256=$Selection.verificationInputs.verifierSha256.linux
}
$Selection.faultProbe = Join-Path $Support 'dev_node_fault_probe.py'
$Selection | ConvertTo-Json -Depth 15 | Set-Content (Join-Path $Support 'inputs.json') -Encoding utf8
